// ====================================================
// Preparar Contexto para IA — G54 Field Mapping
// G54 API fields:
//   company: name, description, value_proposition, base_city, website, emails[], phones[]
//   products: name, description, keywords[]
//   ideas: id, topic, keyword, platform, description
//   estrategia: objetivo, audiencia, tono, cta_principal, embudo, pilares[]
// ====================================================

const empresaRaw = $('📊 Obtener Perfil Empresa').item.json;
// G54 wraps in .data, Airtable uses .fields
const empresa = empresaRaw.data || empresaRaw.fields || empresaRaw || {};

const productosRaw = $('📦 Obtener Servicios Activos').item.json;
// G54: { company_id, data: [{id, name, description, keywords[]}] }
const productosData = productosRaw.data || productosRaw.items || productosRaw.records || (Array.isArray(productosRaw) ? productosRaw : []);

// G54 ideas response: { data: [{id, topic, keyword, platform, description}] }
const temaRaw = $('📅 Obtener Próximo Tema Semanal').item.json;
const temaList = temaRaw.data || temaRaw.items || temaRaw.records || (Array.isArray(temaRaw) ? temaRaw : [temaRaw]);

// Ideas que ya tienen un post generado (cualquier estado: borrador/aprobado/publicado) — para no volver a generar el mismo tema
let usedIdeaIds = new Set();
try {
  const postsRaw = $('📋 Obtener Posts Existentes (G54)').item.json;
  const postsList = postsRaw.data || (Array.isArray(postsRaw) ? postsRaw : []);
  usedIdeaIds = new Set(postsList.map(p => p.social_idea_id).filter(id => id !== null && id !== undefined));
} catch (e) {
  // Si la lectura de posts falla (login caído, etc.), seguimos sin filtrar — mismo comportamiento de antes
}

// Use idea_id from webhook if provided (G54 sends it in mode:post)
const webhookBody = $('🔔 Webhook G54').item?.json?.body || $('🔔 Webhook G54').item?.json || {};
const webhookIdeaId = webhookBody.idea_id;
const temaList2 = Array.isArray(temaList) ? temaList : [temaList];
let temaItem;
if (webhookIdeaId) {
  // Mismo candado anti-duplicado del ítem 117, ahora también para cuando el panel manda
  // un idea_id explícito (botón "Generar Post" sobre una idea puntual) — antes solo protegía
  // la elección automática, así que un clic sobre una idea ya usada volvía a duplicar el post.
  const usedIdsStr = new Set(Array.from(usedIdeaIds).map(id => String(id)));
  if (usedIdsStr.has(String(webhookIdeaId))) {
    throw new Error(`La idea ${webhookIdeaId} ya tiene un post generado — no se crea un duplicado. Para un contenido distinto usá "Regenerar Idea" antes de generar el post, o borrá primero el post existente si es un borrador.`);
  }
  temaItem = temaList2.find(t => String(t.id) === String(webhookIdeaId)) || temaList2[0];
} else {
  // Bug real del 14-ago: el botón "Generar Post" del panel no manda idea_id (confirmado
  // con la ejecución real), así que sin este filtro se podía elegir cualquier idea sin
  // post generado, sin importar su estado — incluida una idea de tendencia todavía sin
  // aprobar, en vez de la idea real que el cliente ya había aprobado en el panel.
  // Nunca generar un post de una idea que un humano no aprobó primero.
  temaItem = temaList2.find(t => !usedIdeaIds.has(t.id) && t.status === 'aprobado');
  if (!temaItem) {
    throw new Error('No hay ninguna idea aprobada y sin usar disponible para generar un post — aprobá una idea en el panel antes de generar el post, o genera ideas nuevas si no hay ninguna pendiente.');
  }
}
temaItem = temaItem || {};
const tema = temaItem.fields || temaItem || {};
const temaId = temaItem.id || temaItem.social_idea_id || temaItem.tema_id || null;

// Estrategia (continueOnFail — null if not configured yet)
const estRaw = $('🎯 Obtener Estrategia RRSS').item?.json || {};
const estrategia = estRaw.data || estRaw || {};

// Build product/service summary — handles G54 (name/description) and Airtable fallback
const servicios = productosData
  .filter(p => (p.fields || p).is_active !== false)
  .map(p => {
    const f = p.fields || p;
    const nombre = f.name || f.nombre || f['Nombre de Servicio'] || '';
    const desc   = f.description || f.descripcion || f['Descripción comercial'] || '';
    const kws    = Array.isArray(f.keywords) ? f.keywords.slice(0,3).join(', ') : '';
    return `- ${nombre}: ${desc}${kws ? ' [' + kws + ']' : ''}`.slice(0, 220);
  })
  .join('\n');

return [{
  json: {
    // ---- Empresa (G54 field names first, Airtable fallback) ----
    empresa_nombre:          empresa.name || empresa.nombre_empresa || empresa['\ufeffnombre_empresa'] || '',
    empresa_descripcion:     empresa.description || empresa.descripcion_corta || '',
    empresa_propuesta_valor: empresa.value_proposition || empresa.propuesta_valor || '',
    empresa_ciudad:          empresa.base_city || empresa.ciudad_base || empresa['ciudad base'] || '',
    empresa_web:             empresa.website || empresa.sitio_web || '',
    empresa_telefono:        (empresa.phones || [])[0] || empresa.telefono || '',
    empresa_email:           (empresa.emails || [])[0] || '',
    empresa_geografia:       empresa.geography || empresa.coverage || '',
    empresa_competidores:    (empresa.competitors_known || []).slice(0,3).map(c => c.name).join(', '),
    servicios_resumen:       servicios,
    // ---- Tema / Idea G54 ----
    tema_id:                 temaId,
    tema_texto:              tema.topic || tema.tema || tema['Tema'] || '',
    tema_descripcion:        tema.fecha_propuesta || '',
    tema_palabras_clave:     tema.keyword || tema.palabras_clave || '',
    keyword_principal:       tema.keyword || tema.keyword_principal || '',
    tema_semana:             tema.week || tema.semana || tema['Semana'] || 0,
    tema_plataforma:         tema.platform || tema.plataforma || 'Instagram',
    fecha_post:              new Date().toISOString().slice(0, 10), // UTC, sin asumir zona horaria de ninguna empresa
    // ---- Estrategia G54 ----
    estrategia_objetivo:     estrategia.objetivo || estrategia.primary_goal || empresa.primary_goal || '',
    estrategia_audiencia:    estrategia.audiencia || estrategia.target_market || empresa.target_market || '',
    estrategia_tono:         estrategia.tono || 'profesional, directo y humano',
    estrategia_cta:          estrategia.link_principal || estrategia.cta_principal || (empresa.website || empresa.sitio_web || ''),
    estrategia_embudo:       estrategia.embudo || 'TOFU-MOFU',
    estrategia_pilares:      Array.isArray(estrategia.pilares) ? estrategia.pilares.join(', ') : (estrategia.pilares || ''),
    // ---- Imagen (G54 provee la URL — subida por usuario o generada por Image AI) ----
    imagen_url:              tema.imagen_url || tema.image_url || null,
    imagen_specs:            tema.imagen_specs || tema.image_specs || '',
  }
}];

const aiResponse = $input.item.json.candidates?.[0]?.content?.parts?.[0]?.text || $input.item.json.choices?.[0]?.message?.content || '{}';
let post;
try {
  post = JSON.parse(aiResponse);
} catch(e) {
  const match = aiResponse.match(/\{[\s\S]*\}/);
  post = match ? JSON.parse(match[0]) : {};
}

const contexto = $('🔧 Preparar Contexto para IA').item.json;

// Normalizar hashtags: array → string
const rawHashtags = post.hashtags || '';
const hashtags = Array.isArray(rawHashtags) ? rawHashtags.join(' ') : rawHashtags;

// Garantizar URL en el CTA (por si la IA no lo incluye) — SOLO con datos reales de ESTA empresa
// (contexto.estrategia_cta ya resuelve estrategia.cta_principal || empresa.website en 🔧 Preparar Contexto para IA).
// Nunca se rellena con el dato de otra empresa: si no hay nada configurado, se marca como pendiente
// en vez de inventar un link, y se dispara una alerta aparte para que se configure.
const QUOTE_URL = contexto.estrategia_cta || '';
let cta = post.cta || '';
let ctaSinConfigurar = false;
if (!cta.includes('http') && !cta.includes('wa.me')) {
  if (QUOTE_URL) {
    cta = cta.trim() + ' → ' + QUOTE_URL;
  } else {
    cta = cta.trim() + ' [CTA PENDIENTE — falta configurar cta_principal o sitio web en G54]';
    ctaSinConfigurar = true;
  }
}

// Envolver el link real del CTA en nuestro tracker de clics — mide cuánta gente hace clic
// en el CTA, algo que Meta no distingue en contenido orgánico. Solo en Facebook: en Instagram
// los links dentro del caption nunca son clicables (Meta no los hipervincula ahí), así que
// envolverlos ahí no mide nada real y solo ensucia el texto con una URL larga.
const platform = (contexto.tema_plataforma || 'Facebook').toLowerCase();
if (QUOTE_URL && cta.includes(QUOTE_URL) && platform !== 'instagram') {
  const companyId = $('⚙️ Config Growth54').item.json.G54_COMPANY_ID;
  const trackedUrl = 'https://n8n.mdarthurdigital.com/webhook/cta-click-g54'
    + '?company=' + encodeURIComponent(companyId)
    + '&platform=' + encodeURIComponent(platform)
    + '&dest=' + encodeURIComponent(QUOTE_URL);
  cta = cta.split(QUOTE_URL).join(trackedUrl);
}

// LinkedIn — mismo hook/CTA, cuerpo reescrito en tono profesional (PASO 9 del prompt).
// Si la IA no lo devuelve (ej. respaldo de Groq viejo sin actualizar), cae al texto de Facebook
// en vez de dejar el campo vacío — mejor un texto real con tono no ideal que ningún texto.
const mensajeLinkedin = post.mensaje_linkedin || post.mensaje || '';
const post_completo_linkedin = [post.hook || '', mensajeLinkedin, cta].filter(Boolean).join('\n\n');

return [{
  json: {
    ...contexto,
    hook_es: post.hook || '',
    mensaje_es: post.mensaje || '',
    cta_es: cta,
    hashtags: hashtags,
    post_completo_es: [post.hook || '', post.mensaje || '', cta].filter(Boolean).join('\n\n'),
    post_completo_linkedin,
    hashtags_es: hashtags,
    texto_canva_titulo: post.texto_canva_titulo || '',
    texto_canva_subtitulo: post.texto_canva_subtitulo || '',
    ctaSinConfigurar
  }
}];

