const postsRaw = $('📋 Buscar Post Nuevo (G54)').item.json;
const postsList = postsRaw.data || (Array.isArray(postsRaw) ? postsRaw : []);

const temaId = $('🔧 Preparar Contexto para IA').item.json.tema_id;

const candidatos = postsList.filter(p => p.social_idea_id === temaId);
// Si hay más de uno (no debería, pero por seguridad) tomamos el más reciente
candidatos.sort((a, b) => new Date(b.created_at) - new Date(a.created_at));
const post = candidatos[0] || null;

if (!post) {
  return [{ json: { encontrado: false, post_id: null } }];
}

return [{ json: {
  encontrado: true,
  post_id: post.id,
  platform: post.platform,
  company_id: $('⚙️ Config Growth54').item.json.G54_COMPANY_ID,
}}];
